 add('ap-count',rf'সসীম সমান্তর ধারা ${k},{2*k},{3*k},\ldots,{k*(k+4)}$।',Q('সাধারণ অন্তর কত?',k,rf'${2*k}-{k}={k}$।'),Q('পদসংখ্যা কত?',k+4,rf'$l=a+(n-1)d$ থেকে ${k*(k+4)}={k}+(n-1){k}$; n={k+4}।'),Q('সব পদের যোগ কত?',k*(k+4)*(k+5)/2,rf'$S=\frac{{{k+4}}}2[{k}+{k*(k+4)}]={T(k*(k+4)*(k+5)/2)}$।'),k=k)
 add('arithmetic-means',rf'{k} ও {7*k}-এর মাঝে 5টি সমান্তর মধ্যক বসানো হলো, ফলে মোট 7টি পদ।',Q('প্রথম থেকে শেষ পর্যন্ত অন্তর কয়টি?',6,'মোট 7টি পদে পাশাপাশি অন্তর 6টি।'),Q('সাধারণ অন্তর কত?',k,rf'$d=({7*k}-{k})/6={k}$।'),Q('মধ্যকগুলোর যোগ কত?',20*k,rf'পাঁচ মধ্যক ${2*k},{3*k},{4*k},{5*k},{6*k}$; যোগ $20\times{k}={20*k}$।'),k=k)
