 add('gp-term',rf'সসীম গুণোত্তর ধারার প্রথম পদ {k}, সাধারণ অনুপাত 2; প্রথম {N} পদ বিবেচ্য।',Q('তৃতীয় পদ কত?',4*k,rf'$a_3=ar^2={k}\times2^2={4*k}$।'),Q(rf'{N}-তম পদ কত?',k*2**(N-1),rf'$a_n=ar^{{n-1}}$ থেকে ${k}\times2^{{{N-1}}}={k*2**(N-1)}$।'),Q('বিবেচ্য সব পদের যোগ কত?',k*(2**N-1),rf'$S_n=a(r^n-1)/(r-1)$; $S={k}(2^{{{N}}}-1)={k*(2**N-1)}$।'),k=k)
